import React, { useState } from 'react';
import MeshSphere from '../components/MeshSphere';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

const TRAPS = ['Katastrofiering','Tankeläsning','Svartvitt tänkande','Övergeneralisering','Känslomässigt resonerande','Personalisering','Filtrerande','Bör-tänkande'];

export default function Home({ setPage, streak }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const { addThought } = useThoughts();

  const handleSubmit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id:Date.now(), user_text:text, ...ai, date:new Date().toISOString() };
      addThought(entry);
      setResult(entry);
    } catch { setError('Kunde inte analysera. Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={()=>{ setResult(null); setText(''); }} setPage={setPage} />;

  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:80, position:'relative', overflow:'hidden' }}>

      {/* Background grid lines */}
      <div style={{ position:'absolute', inset:0, backgroundImage:'linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px)', backgroundSize:'48px 48px', pointerEvents:'none' }} />

      {/* Huge mesh sphere — top half of screen */}
      <div style={{ display:'flex', justifyContent:'center', marginTop:8, position:'relative', animation:'fadeIn .8s ease both' }}>
        <div style={{ position:'relative' }}>
          <MeshSphere size={340} speed={0.5} distort={0.7} color='#f2f0eb' />

          {/* Streak badge floating over sphere */}
          {streak > 0 && (
            <div style={{ position:'absolute', top:40, right:-10, background:'#f2f0eb', color:'#0c0c0e', padding:'5px 12px', borderRadius:100, fontSize:11, fontWeight:700, fontFamily:'DM Mono,monospace', letterSpacing:'0.06em', display:'flex', alignItems:'center', gap:5 }}>
              🔥{streak}
            </div>
          )}

          {/* Label below sphere */}
          <div style={{ position:'absolute', bottom:32, left:'50%', transform:'translateX(-50%)', whiteSpace:'nowrap', display:'flex', alignItems:'center', gap:8 }}>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.24em', textTransform:'uppercase', color:'rgba(242,240,235,0.3)' }}>Tankemönster · Identifiering</span>
          </div>
        </div>
      </div>

      {/* Bold heading — centered, breaks into lines */}
      <div style={{ padding:'0 24px', textAlign:'center', marginBottom:28, animation:'fadeUp .8s .15s both' }}>
        <h1 style={{ fontSize:'clamp(36px,9vw,60px)', fontWeight:900, letterSpacing:'-0.06em', lineHeight:0.88, color:'#f2f0eb', textTransform:'uppercase' }}>
          BRYT<br/>
          <span style={{ color:'rgba(242,240,235,0.2)' }}>SPIRALEN</span>
        </h1>
      </div>

      {/* Scrolling ticker of trap names */}
      <div style={{ overflow:'hidden', marginBottom:28, borderTop:'1px solid rgba(255,255,255,0.06)', borderBottom:'1px solid rgba(255,255,255,0.06)', padding:'8px 0' }}>
        <div style={{ display:'flex', gap:0, animation:'ticker 24s linear infinite', width:'200%' }}>
          {[...TRAPS, ...TRAPS].map((trap, i) => (
            <span key={i} style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(242,240,235,0.22)', whiteSpace:'nowrap', padding:'0 24px' }}>
              {trap} ·
            </span>
          ))}
        </div>
      </div>

      {/* Input area */}
      <div style={{ padding:'0 20px', animation:'fadeUp .8s .25s both' }}>
        <div style={{ position:'relative', border:'1px solid rgba(255,255,255,0.1)', borderRadius:4, overflow:'hidden', background:'rgba(255,255,255,0.03)' }}>
          {/* Corner decorators — like the reference UI */}
          <div style={{ position:'absolute', top:0, left:0, width:12, height:12, borderTop:'1.5px solid rgba(255,255,255,0.4)', borderLeft:'1.5px solid rgba(255,255,255,0.4)' }} />
          <div style={{ position:'absolute', top:0, right:0, width:12, height:12, borderTop:'1.5px solid rgba(255,255,255,0.4)', borderRight:'1.5px solid rgba(255,255,255,0.4)' }} />
          <div style={{ position:'absolute', bottom:0, left:0, width:12, height:12, borderBottom:'1.5px solid rgba(255,255,255,0.4)', borderLeft:'1.5px solid rgba(255,255,255,0.4)' }} />
          <div style={{ position:'absolute', bottom:0, right:0, width:12, height:12, borderBottom:'1.5px solid rgba(255,255,255,0.4)', borderRight:'1.5px solid rgba(255,255,255,0.4)' }} />

          <div style={{ padding:'14px 16px 8px' }}>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.3)', marginBottom:10, display:'flex', alignItems:'center', gap:8 }}>
              <span style={{ width:5, height:5, borderRadius:'50%', background:'rgba(242,240,235,0.5)', display:'inline-block', animation:'pulse 2s infinite' }} />
              Input
            </div>
            <textarea value={text} onChange={e=>setText(e.target.value)} maxLength={1000}
              placeholder="Vad snurrar i huvudet just nu?"
              style={{ width:'100%', minHeight:100, background:'transparent', border:'none', color:'#f2f0eb', fontSize:15, fontWeight:300, lineHeight:1.8, resize:'none', outline:'none', letterSpacing:'0.01em' }}
            />
          </div>

          <div style={{ borderTop:'1px solid rgba(255,255,255,0.06)', padding:'10px 16px', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(242,240,235,0.2)' }}>{text.length}/1000</span>
            <button onClick={handleSubmit} disabled={!text.trim()||loading}
              style={{ display:'flex', alignItems:'center', gap:8, padding:'8px 18px', borderRadius:2, background: text.trim()&&!loading ? '#f2f0eb' : 'rgba(255,255,255,0.07)', color: text.trim()&&!loading ? '#0c0c0e' : 'rgba(242,240,235,0.25)', fontSize:11, fontWeight:700, letterSpacing:'0.12em', textTransform:'uppercase', fontFamily:'DM Mono,monospace', transition:'all .2s' }}>
              {loading
                ? <><span style={{ width:10,height:10,border:'2px solid rgba(0,0,0,0.2)',borderTopColor:'#0c0c0e',borderRadius:'50%',display:'inline-block',animation:'spin .7s linear infinite' }}/>Analyserar</>
                : 'Analysera →'}
            </button>
          </div>
          {error && <p style={{ padding:'0 16px 12px', color:'rgba(255,100,100,0.8)', fontSize:12 }}>{error}</p>}
        </div>

        {/* Quick action row */}
        <div style={{ display:'flex', gap:8, marginTop:10 }}>
          <button onClick={()=>setPage('checkin')}
            style={{ flex:1, padding:'12px', border:'1px solid rgba(255,255,255,0.08)', borderRadius:4, background:'rgba(255,255,255,0.03)', color:'rgba(242,240,235,0.5)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.1em', textTransform:'uppercase', transition:'all .2s', display:'flex', alignItems:'center', justifyContent:'center', gap:8 }}
            onMouseEnter={e=>{e.currentTarget.style.borderColor='rgba(255,255,255,0.2)';e.currentTarget.style.color='#f2f0eb'}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor='rgba(255,255,255,0.08)';e.currentTarget.style.color='rgba(242,240,235,0.5)'}}>
            ◈ Check-in
          </button>
          <button onClick={()=>setPage('breathing')}
            style={{ flex:1, padding:'12px', border:'1px solid rgba(255,255,255,0.08)', borderRadius:4, background:'rgba(255,255,255,0.03)', color:'rgba(242,240,235,0.5)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.1em', textTransform:'uppercase', transition:'all .2s', display:'flex', alignItems:'center', justifyContent:'center', gap:8 }}
            onMouseEnter={e=>{e.currentTarget.style.borderColor='rgba(255,255,255,0.2)';e.currentTarget.style.color='#f2f0eb'}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor='rgba(255,255,255,0.08)';e.currentTarget.style.color='rgba(242,240,235,0.5)'}}>
            ◯ Andning
          </button>
        </div>
      </div>
    </div>
  );
}

function Analysis({ result, text, onBack, setPage }) {
  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:80, overflow:'hidden', position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px)', backgroundSize:'48px 48px', pointerEvents:'none' }} />

      <div style={{ padding:'24px 20px 0', animation:'fadeUp .6s cubic-bezier(0.16,1,0.3,1) both' }}>

        {/* Small mesh in corner */}
        <div style={{ display:'flex', justifyContent:'center', marginBottom:16 }}>
          <MeshSphere size={180} speed={0.3} distort={1.2} color='#f2f0eb' />
        </div>

        {/* What you wrote */}
        <div style={{ border:'1px solid rgba(255,255,255,0.07)', borderRadius:4, padding:'12px 16px', marginBottom:20, position:'relative' }}>
          <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.25)', marginBottom:8 }}>Input</div>
          <p style={{ fontSize:13, color:'rgba(242,240,235,0.45)', fontStyle:'italic', lineHeight:1.7 }}>"{text.slice(0,140)}{text.length>140?'...':''}"</p>
        </div>

        {/* Big trap name */}
        <div style={{ marginBottom:20 }}>
          <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:6 }}>{result.trap_icon} Tankefälla identifierad</div>
          <h2 style={{ fontSize:'clamp(28px,7vw,48px)', fontWeight:900, letterSpacing:'-0.05em', lineHeight:0.9, color:'#f2f0eb', textTransform:'uppercase' }}>{result.trap_label}</h2>
        </div>

        {/* Info blocks — stacked with corner brackets */}
        {[
          { label:'Analys',    body:result.description },
          { label:'Omramning', body:result.reframe },
          { label:'Övning',    body:result.exercise_text },
        ].map(({ label, body }) => (
          <div key={label} style={{ marginBottom:12, position:'relative', border:'1px solid rgba(255,255,255,0.07)', borderRadius:4, padding:'14px 16px', background:'rgba(255,255,255,0.025)' }}>
            <div style={{ position:'absolute', top:0, left:0, width:8, height:8, borderTop:'1px solid rgba(255,255,255,0.3)', borderLeft:'1px solid rgba(255,255,255,0.3)' }} />
            <div style={{ position:'absolute', bottom:0, right:0, width:8, height:8, borderBottom:'1px solid rgba(255,255,255,0.3)', borderRight:'1px solid rgba(255,255,255,0.3)' }} />
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:8 }}>{label}</div>
            <p style={{ fontSize:13, color:'rgba(242,240,235,0.75)', lineHeight:1.85, fontWeight:300 }}>{body}</p>
          </div>
        ))}

        <div style={{ display:'flex', gap:8, marginTop:4 }}>
          <button onClick={()=>setPage('breathing')}
            style={{ flex:1, padding:'12px', border:'1px solid rgba(255,255,255,0.1)', borderRadius:4, background:'rgba(255,255,255,0.05)', color:'rgba(242,240,235,0.6)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.1em', textTransform:'uppercase' }}>
            ◯ Andning
          </button>
          <button onClick={onBack}
            style={{ padding:'12px 20px', fontSize:11, color:'rgba(242,240,235,0.28)', fontFamily:'DM Mono,monospace', letterSpacing:'0.1em', textTransform:'uppercase' }}>
            ← Tillbaka
          </button>
        </div>
      </div>
    </div>
  );
}
